DROP POLICY IF EXISTS organization_preferences_manage ON public.organization_preferences;
DROP POLICY IF EXISTS organization_preferences_read ON public.organization_preferences;
CREATE POLICY organization_preferences_select ON public.organization_preferences FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.organization_members om WHERE om.organization_id=organization_preferences.organization_id AND om.user_id=(SELECT auth.uid()) AND om.status='active'));
CREATE POLICY organization_preferences_insert ON public.organization_preferences FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.organization_members om WHERE om.organization_id=organization_preferences.organization_id AND om.user_id=(SELECT auth.uid()) AND om.status='active' AND om.role IN ('owner','admin','director')));
CREATE POLICY organization_preferences_update ON public.organization_preferences FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.organization_members om WHERE om.organization_id=organization_preferences.organization_id AND om.user_id=(SELECT auth.uid()) AND om.status='active' AND om.role IN ('owner','admin','director'))) WITH CHECK (EXISTS (SELECT 1 FROM public.organization_members om WHERE om.organization_id=organization_preferences.organization_id AND om.user_id=(SELECT auth.uid()) AND om.status='active' AND om.role IN ('owner','admin','director')));
CREATE POLICY organization_preferences_delete ON public.organization_preferences FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.organization_members om WHERE om.organization_id=organization_preferences.organization_id AND om.user_id=(SELECT auth.uid()) AND om.status='active' AND om.role IN ('owner','admin','director')));